import xml.etree.ElementTree as ET
import datetime
import dateutil.parser
import json
import re
import os
import subprocess

FEEDS = [
    {"source": "CoinDesk", "file": "/tmp/coindesk.xml"},
    {"source": "CoinTelegraph", "file": "/tmp/cointelegraph.xml"},
    {"source": "Decrypt", "file": "/tmp/decrypt.xml"},
    {"source": "Google News", "file": "/tmp/googlenews.xml"},
    {"source": "BeInCrypto", "file": "/tmp/beincrypto.xml"},
    {"source": "The Block", "file": "/tmp/theblock.xml"},
    {"source": "CryptoSlate", "file": "/tmp/cryptoslate.xml"},
    {"source": "CryptoFox", "file": "/tmp/cryptofox_markets.xml"},
    {"source": "CryptoFox", "file": "/tmp/cryptofox_regulation.xml"}
]

MEME_KEYWORDS = ["doge", "shib", "pepe", "bonk", "wif", "floki", "memecoin", "meme coin"]

def extract_text(element):
    if element is not None and element.text:
        return re.sub(r'<[^>]+>', '', element.text).strip()
    return ""

def parse_date(date_str):
    try:
        dt = dateutil.parser.parse(date_str)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt
    except:
        return None

now = datetime.datetime.now(datetime.timezone.utc)
cutoff = now - datetime.timedelta(hours=24)

all_items = []

for feed in FEEDS:
    if not os.path.exists(feed["file"]): continue
    try:
        tree = ET.parse(feed["file"])
        root = tree.getroot()
        channel = root.find('channel')
        if channel is None: continue

        for idx, item in enumerate(channel.findall('item')):
            headline = extract_text(item.find('title'))
            url = extract_text(item.find('link'))
            pub_date_str = extract_text(item.find('pubDate'))
            summary = extract_text(item.find('description'))[:280]

            # Google news url fix
            if "news.google.com" in url:
                continue # for simplicity, skip google news items if they are tricky to parse URL, or keep original

            pub_date = parse_date(pub_date_str)
            if pub_date and pub_date < cutoff:
                continue

            if not pub_date and idx >= 5:
                continue

            if not url or url.startswith("mailto:") or url.startswith("javascript:"):
                continue

            headline_lower = headline.lower()
            if any(meme in headline_lower for meme in MEME_KEYWORDS):
                continue

            all_items.append({
                "headline": headline,
                "url": url,
                "pub_date": pub_date.isoformat() if pub_date else "",
                "source": feed["source"],
                "summary": summary,
                "corroborating_sources": [],
                "_pub_date_obj": pub_date
            })
    except Exception as e:
        print(f"Error parsing {feed['file']}: {e}")

# Deduplicate
def get_words(text):
    return set(re.findall(r'\w+', text.lower()))

PRIORITY = {"CoinDesk": 8, "CoinTelegraph": 7, "Decrypt": 6, "The Block": 5, "BeInCrypto": 4, "CryptoSlate": 3, "CryptoFox": 2, "Google News": 1}

deduped = []
for item in all_items:
    duplicate_of = None
    for d in deduped:
        if item["url"] == d["url"]:
            duplicate_of = d
            break

        w1 = get_words(item["headline"])
        w2 = get_words(d["headline"])
        if len(w1) > 0 and len(w2) > 0:
            overlap = len(w1.intersection(w2)) / max(len(w1), len(w2))
            if overlap >= 0.8:
                duplicate_of = d
                break

    if duplicate_of:
        if PRIORITY.get(item["source"], 0) > PRIORITY.get(duplicate_of["source"], 0):
            # replace duplicate_of with item, keep corroborating
            item["corroborating_sources"] = duplicate_of["corroborating_sources"][:2]
            if len(item["corroborating_sources"]) < 2:
                item["corroborating_sources"].append({"source": duplicate_of["source"], "url": duplicate_of["url"]})
            duplicate_of.update(item)
        else:
            if len(duplicate_of["corroborating_sources"]) < 2:
                duplicate_of["corroborating_sources"].append({"source": item["source"], "url": item["url"]})
    else:
        deduped.append(item)

# Sort
deduped.sort(key=lambda x: x["_pub_date_obj"] or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc), reverse=True)

# History Check
final_candidates = []
for item in deduped:
    if len(final_candidates) >= 10: break

    url = item["url"]
    cmd = ["bash", "/home/bhard/.openclaw/workspace-researcher/skills/history/article_history.sh", "check", url]
    try:
        res = subprocess.run(cmd, capture_output=True, text=True)
        if "NOT_FOUND" in res.stdout:
            del item["_pub_date_obj"]
            item["candidate_index"] = len(final_candidates) + 1
            final_candidates.append(item)
    except Exception as e:
        print(f"Error checking history for {url}: {e}")

output = {
    "status": "ok",
    "mode": "headline_scan",
    "scanned_at": datetime.datetime.now(datetime.timezone.utc).isoformat(),
    "target_count": 10,
    "candidate_count": len(final_candidates),
    "candidates": final_candidates
}

with open("/tmp/crypto-run-20260603-114226/research/headlines.json", "w") as f:
    json.dump(output, f, indent=2)

print(f"Saved {len(final_candidates)} candidates.")
EOF
